"""Generated by scripts/build/design-tokens.sh from design/tokens.json -- do not edit; change the tokens and run it again.

From which zoom each kind of airport, airspace and navaid is drawn (design/tokens.json's map.zoom),
in the app's levels, MapLibre's + 1."""

#: The farthest out the airports' layer is drawn, where its marks are smallest; each field within it
#: from its own tier's zoom below.
AIRPORTS_FARTHEST = 4

#: Towered fields (field_mark_rank's first tier), a few states on a phone, with the Class B and C they
#: are named for.
AIRPORT_TOWERED = 5

#: Public fields with a hard runway of 3,000 ft or more (field_mark_rank's second tier).
AIRPORT_LONG_HARD = 7

#: Every other public field (field_mark_rank's third tier).
AIRPORT_PUBLIC = 8

#: Private fields (field_mark_rank's fourth tier), behind their switch.
AIRPORT_PRIVATE = 10

#: Heliports (field_mark_rank's last tier).
AIRPORT_HELIPORT = 11

#: Every drawn field's ident from this zoom; farther out only a Class B field's, as there an ident is
#: wider than the room between two towered fields.
AIRPORT_IDENTS = 6

#: Class B rings.
AIRSPACE_B = 5

#: Class C rings.
AIRSPACE_C = 5

#: Class D rings.
AIRSPACE_D = 7

#: Class E at the surface and a Class C's or D's surface-area extensions (E2, E3, E4): in the tiles,
#: not drawn on the 2D map.
AIRSPACE_E_SURFACE = 8

#: Every other Class E (E5, E6, E7): in the tiles, not drawn on the 2D map.
AIRSPACE_E = 9

#: The rings at their full width with their band inside; farther out half their width and no band, so a
#: Class C is a ring and not a dot.
AIRSPACE_FULL = 7

#: The airspace and special-use altitude tabs: farther out they were the largest marks on the map, over
#: the fields' names (the owner, 2026-11-20).
AIRSPACE_LABELS = 9

#: Restricted, prohibited and warning areas and MOAs: at 6 California's 160 hatched lines hid the
#: fields and the Class B and C under them (2026-11-21).
SPECIAL_USE = 7

#: The VORs a pilot tunes (NASR's NAV_TYPE VOR, VOR/DME and VORTAC), from a region's zoom. The app's
#: alone: the charts job's tiles hold every navaid from its own zooms (overlay_layers).
VOR = 8

#: The VFR waypoints and the low enroute chart's fixes. The app's alone: the charts job's tiles hold
#: every fix from its own zooms (overlay_layers).
FIX = 10

#: The Class B fields' weather marks at their full size and named from this zoom; farther out, over the
#: whole country, each a small mark with no ident that gives way to the route's own, so only the
#: route's ends and stops are named there (the owner's iPhone screenshot, 2026-11-23).
CLASS_B_NAMED = 5

#: The route's tags beyond its fields and stops, its tops of climb and descent, from this zoom, where a
#: leg is long enough on a phone to read them; farther out the route is its line, its ends and its
#: stops.
ROUTE_TAGS = 6

#: A procedure's fixes' tags and an approach plate's fix tags from this zoom; farther out an approach
#: is a short line by its field, and its words would cover it and the fields round it.
PROCEDURE_WORDS = 9
